// Simplified upward bump allocator (no overflow checks)
typedef struct { uintptr_t start, end, ptr; } Bump;

void *bump_alloc(Bump *b, size_t size, size_t align) {
    uintptr_t aligned = (b->ptr + align - 1) & ~(align - 1);
    uintptr_t new_ptr = aligned + size;
    if (new_ptr > b->end)
        return NULL;            // chunk full: caller grabs a new chunk
    b->ptr = new_ptr;
    return (void *)aligned;
}

void bump_reset(Bump *b) { b->ptr = b->start; }  // free everything

